import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">

          <p className="tag">WELCOME TO MY PORTFOLIO</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • Problem Solver • Tech Explorer
          </h2>

          <p className="desc">
            I enjoy building scalable systems, clean UI experiences, and real-world applications
            that solve meaningful problems through structured thinking.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT SIDE - TERMINAL */}
        <div className="right">

          <div className="terminal">

            <div className="terminal-header">
              <span className="dot red"></span>
              <span className="dot yellow"></span>
              <span className="dot green"></span>
              <span className="title">developer.sh</span>
            </div>

            <div className="terminal-body">

              <p>> name: Swetha A</p>
              <p>> role: Full Stack Developer</p>
              <p>> education: IT Student</p>
              <p>> college: Panimalar Engineering College</p>
              <p>> cgpa: 8.81</p>
              <p>> focus: Web Apps, UI Systems, Backend Logic</p>
              <p>> status: Building impactful projects...</p>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 2px;
          color: #64748b;
          margin-bottom: 15px;
        }

        h1 {
          font-size: 60px;
          margin: 0;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
          margin-top: 10px;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          cursor: pointer;
          transition: 0.3s;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .primary:hover {
          transform: translateY(-2px);
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        .secondary:hover {
          background: rgba(56,189,248,0.08);
        }

        /* TERMINAL */
        .terminal {
          background: #0a0f1a;
          border: 1px solid rgba(56,189,248,0.2);
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 0 25px rgba(56,189,248,0.08);
        }

        .terminal-header {
          display: flex;
          align-items: center;
          gap: 8px;
          padding: 10px 14px;
          background: rgba(255,255,255,0.03);
        }

        .dot {
          width: 10px;
          height: 10px;
          border-radius: 50%;
        }

        .red { background: #ff5f56; }
        .yellow { background: #ffbd2e; }
        .green { background: #27c93f; }

        .title {
          margin-left: 10px;
          font-size: 12px;
          color: #94a3b8;
        }

        .terminal-body {
          padding: 18px;
          font-family: monospace;
          font-size: 14px;
          color: #38BDF8;
          line-height: 1.8;
        }

        .terminal-body p {
          margin: 0;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          .buttons {
            justify-content: center;
          }

          h1 {
            font-size: 42px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
